%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[GP_FFCutsFits,CutFitFileGP] = recover_selected_cuts('GP_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

%%
fn = fieldnames(GP_FFCutsFits);
%nf = 11
%for nf = 2:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei800_off200GPminFF'; %[output:2205210d]
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end


fprintf('Processing cuts: %s \n', selectCuts); %[output:0efda4b6]
%selectCuts= 'Ei400_off200GPmaxFF';
cuts_list = GP_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    min_Ei = 30;    
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    min_Ei = 40;    
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    min_Ei =70;    
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list) %[output:group:7b25fb50]
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 1; keep_figure; %[output:9ba714c1]
end %[output:group:7b25fb50]
dir_name  = "GP";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(30,en_mm(1));
%en_mm(1) = 100;
%en_mm(2) = 170;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
GP_FFCutsFits.(selectCuts) = cuts_list;

GP_FFCutsFits = fit_multicutsFF_along_direction(... %[output:group:4fa25ffe] %[output:788427f4] %[output:7a164126] %[output:7fff8b30] %[output:7b9605d4] %[output:7250f420] %[output:616a9f2f] %[output:02140602] %[output:02f1d8e7] %[output:22af899b] %[output:54734319] %[output:503fab2d] %[output:01c64792] %[output:98aaea7c] %[output:6b6449ba] %[output:9e8e909a] %[output:5be12ae7] %[output:60247e0c] %[output:3e300c0e] %[output:3100341e] %[output:8919be48] %[output:672c4f88] %[output:2a0ff703] %[output:5150b042] %[output:6c4f9849] %[output:1818a189] %[output:85a962d8] %[output:3c522fa3] %[output:3258224e] %[output:4033ef34] %[output:1b9179e2] %[output:409e22e8] %[output:2c2f08a2] %[output:85b239c2] %[output:5105bdbf] %[output:71a15a26] %[output:15a8dae5] %[output:3f1d816a] %[output:6b6104c8] %[output:5111e7e9] %[output:3170a360] %[output:9c37e8c5] %[output:43408d1c] %[output:810058b4] %[output:835ab41a] %[output:3d5ec564] %[output:91789752] %[output:81816b2a] %[output:776f5a7e] %[output:18f4277e] %[output:9fc1da64] %[output:3cf9ca96] %[output:049da012] %[output:4bffe540] %[output:8b0758ad] %[output:73da45c8] %[output:56289059] %[output:247e91fd] %[output:4c806419] %[output:5606db76] %[output:40a72ae3] %[output:3308e189] %[output:339e5946] %[output:71d16cb3] %[output:12066f6e] %[output:12517bd2] %[output:81363cb1] %[output:3e5b60ec] %[output:617475d7] %[output:8b5f762a]
    GP_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:4fa25ffe] %[output:788427f4] %[output:7a164126] %[output:7fff8b30] %[output:7b9605d4] %[output:7250f420] %[output:616a9f2f] %[output:02140602] %[output:02f1d8e7] %[output:22af899b] %[output:54734319] %[output:503fab2d] %[output:01c64792] %[output:98aaea7c] %[output:6b6449ba] %[output:9e8e909a] %[output:5be12ae7] %[output:60247e0c] %[output:3e300c0e] %[output:3100341e] %[output:8919be48] %[output:672c4f88] %[output:2a0ff703] %[output:5150b042] %[output:6c4f9849] %[output:1818a189] %[output:85a962d8] %[output:3c522fa3] %[output:3258224e] %[output:4033ef34] %[output:1b9179e2] %[output:409e22e8] %[output:2c2f08a2] %[output:85b239c2] %[output:5105bdbf] %[output:71a15a26] %[output:15a8dae5] %[output:3f1d816a] %[output:6b6104c8] %[output:5111e7e9] %[output:3170a360] %[output:9c37e8c5] %[output:43408d1c] %[output:810058b4] %[output:835ab41a] %[output:3d5ec564] %[output:91789752] %[output:81816b2a] %[output:776f5a7e] %[output:18f4277e] %[output:9fc1da64] %[output:3cf9ca96] %[output:049da012] %[output:4bffe540] %[output:8b0758ad] %[output:73da45c8] %[output:56289059] %[output:247e91fd] %[output:4c806419] %[output:5606db76] %[output:40a72ae3] %[output:3308e189] %[output:339e5946] %[output:71d16cb3] %[output:12066f6e] %[output:12517bd2] %[output:81363cb1] %[output:3e5b60ec] %[output:617475d7] %[output:8b5f762a]
cl = GP_FFCutsFits.(selectCuts);
GP_FFCutsFits.(selectCuts) = [cl{:}];

beep
beep
beep

all_fit_par = GP_FFCutsFits.([selectCuts,'_all_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure; %[output:4193ccc1]
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure %[output:345b4c58]
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_GP.mlx';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_GP_',selectCuts,'.pdf']);
export(thisFile,targ_file);
%close all;

fit_src_struc = GP_FFCutsFits;
save(CutFitFileGP,"fit_src_struc",'-v7.3')
%end

